WITH with_gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) > INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM transactions), sessions_transactions AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, SUM(is_new_burst) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT DATE_TRUNC('YEAR', txn_time) AS year_start, burst_id, txn_type, SORT_ARRAY(COLLECT_SET(txn_type)) AS txn_type_list, APPROX_PERCENTILE(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS span_minutes, SUM(CASE WHEN txn_type = 'REFUND' THEN burst_id ELSE 0 END) AS refund_burst_id, MIN(txn_time) AS started_at, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN txn_type = 'DEBIT' THEN 1 END), 0), 2) AS amount_per_debit FROM sessions_transactions GROUP BY GROUPING SETS ((DATE_TRUNC('YEAR', txn_time), burst_id, txn_type), (DATE_TRUNC('YEAR', txn_time), burst_id), (DATE_TRUNC('YEAR', txn_time)), ()) ORDER BY txn_type DESC NULLS FIRST;
